<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableTypeAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateVariableTypeAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateVariableTypeAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getType returns null on a freshly created holder.
     */
    public function testTypeNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVariableTypeAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTypeAssigned());
        $this->assertNull($holder->getType());
    }
}
class ImplWithTemplateVariableTypeAttributeHolderUnitTest
{
    use TemplateVariableTypeAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTypeRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultType();
    }
}
